import{_ as p,a0 as l,w as o,s as d,I as t,x as e,a1 as a,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"使用 Docker 企业版搭建自己的私有注册服务器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Docker 企业版搭建自己的私有注册服务器 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Docker 企业版搭建自己的私有注册服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Docker 企业版搭建自己的私有注册服务器 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180110 Using Your Own Private Registry with Docker Enterprise Edition","title":"使用 Docker 企业版搭建自己的私有注册服务器","tag":"201811","desc":""},"relativePath":"201811/20180110 Using Your Own Private Registry with Docker Enterprise Edition.md","filePath":"[post].md"}'),k={name:"201811/20180110 Using Your Own Private Registry with Docker Enterprise Edition.md"};function u(g,s,c,T,D,h){const n=l("Link");return o(),d("div",null,[s[26]||(s[26]=t("h1",{id:"使用-docker-企业版搭建自己的私有注册服务器",tabindex:"-1"},[e("使用 Docker 企业版搭建自己的私有注册服务器 "),t("a",{class:"header-anchor",href:"#使用-docker-企业版搭建自己的私有注册服务器","aria-label":"Permalink to “使用 Docker 企业版搭建自己的私有注册服务器”"},"​")],-1)),s[27]||(s[27]=t("p",null,[t("img",{src:"https://i1.wp.com/blog.docker.com/wp-content/uploads/ccd278d2-29c2-4866-8285-c2fe60b4bd5e-1.jpg?resize=965%2C452&ssl=1",alt:"docker trusted registry"})],-1)),t("p",null,[s[1]||(s[1]=e("Docker 真的很酷，特别是和使用虚拟机相比，转移 Docker 镜像十分容易。如果你已准备好使用 Docker，那你肯定已从 ",-1)),a(n,{href:"https://hub.docker.com/"},{default:i(()=>[...s[0]||(s[0]=[e("Docker Hub",-1)])]),_:1}),s[2]||(s[2]=e(" 上拉取过完整的镜像。Docker Hub 是 Docker 的云端注册服务器服务，它包含成千上万个供选择的 Docker 镜像。如果你开发了自己的软件包并创建了自己的 Docker 镜像，那么你会想有自己私有的注册服务器。如果你有搭配着专有许可的镜像，或想为你的构建系统提供复杂的持续集成（CI）过程，则更应该拥有自己的私有注册服务器。",-1))]),t("p",null,[s[5]||(s[5]=e("Docker 企业版包括 ",-1)),s[6]||(s[6]=t("ruby",null,[e("Docker 可信注册服务器"),t("rt",null,"Docker Trusted Registry")],-1)),s[7]||(s[7]=e("（DTR）。这是一个具有安全镜像管理功能的高可用的注册服务器，为在你自己的数据中心或基于云端的架构上运行而构建。在接下来，我们将了解到 DTR 是提供安全、可重用且连续的",-1)),a(n,{href:"https://blog.docker.com/2016/08/securing-enterprise-software-supply-chain-using-docker/"},{default:i(()=>[...s[3]||(s[3]=[e("软件供应链",-1)])]),_:1}),s[8]||(s[8]=e("的一个关键组件。你可以通过我们的",-1)),a(n,{href:"https://www.docker.com/trial"},{default:i(()=>[...s[4]||(s[4]=[e("免费托管小样",-1)])]),_:1}),s[9]||(s[9]=e("立即开始使用，或者通过下载安装进行 30 天的免费试用。下面是开始自己安装的步骤。",-1))]),s[28]||(s[28]=r(`<h3 id="配置-docker-企业版" tabindex="-1">配置 Docker 企业版 <a class="header-anchor" href="#配置-docker-企业版" aria-label="Permalink to “配置 Docker 企业版”">​</a></h3><p>DTR 运行于通用控制面板（UCP）之上，所以开始前要安装一个单节点集群。如果你已经有了自己的 UCP 集群，可以跳过这一步。在你的 docker 托管主机上，运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 拉取并安装 UCP</span></span>
<span class="line"><span>docker run -it -rm -v /var/run/docker.sock:/var/run/docker.sock -name ucp docker/ucp:latest install</span></span></code></pre></div>`,3)),t("p",null,[s[11]||(s[11]=e("当 UCP 启动并运行后，在安装 DTR 之前你还有几件事要做。针对刚刚安装的 UCP 实例，打开浏览器。在日志输出的末尾应该有一个链接。如果你已经有了 Docker 企业版的许可证，那就在这个界面上输入它吧。如果你还没有，可以访问 ",-1)),a(n,{href:"https://store.docker.com/search?offering=enterprise&page=1&q=&type=edition"},{default:i(()=>[...s[10]||(s[10]=[e("Docker 商店",-1)])]),_:1}),s[12]||(s[12]=e("获取 30 天的免费试用版。",-1))]),s[29]||(s[29]=r(`<p>准备好许可证后，你可能会需要改变一下 UCP 运行的端口。因为这是一个单节点集群，DTR 和 UCP 可能会以相同的端口运行它们的 web 服务。如果你拥有不只一个节点的 UCP 集群，这就不是问题，因为 DTR 会寻找有所需空闲端口的节点。在 UCP 中，点击“管理员设置 -&gt; 集群配置”并修改控制器端口，比如 5443。</p><h3 id="安装-dtr" tabindex="-1">安装 DTR <a class="header-anchor" href="#安装-dtr" aria-label="Permalink to “安装 DTR”">​</a></h3><p>我们要安装一个简单的、单节点的 DTR 实例。如果你要安装实际生产用途的 DTR，那么你会将其设置为高可用（HA）模式，即需要另一种存储介质，比如基于云端的对象存储或者 NFS（LCTT 译注：Network File System，网络文件系统）。因为目前安装的是一个单节点实例，我们依然使用默认的本地存储。</p><p>首先我们需要拉取 DTR 的 bootstrap 镜像。boostrap 镜像是一个微小的独立安装程序，包括了连接到 UCP 以及设置和启动 DTR 所需的所有容器、卷和逻辑网络。</p><p>使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 拉取并运行 DTR 引导程序</span></span>
<span class="line"><span>docker run -it -rm docker/dtr:latest install -ucp-insecure-tls</span></span></code></pre></div><p>注意：默认情况下，UCP 和 DTR 都有自己的证书，系统无法识别。如果你已使用系统信任的 TLS 证书设置 UCP，则可以省略 <code>-ucp-insecure-tls</code> 选项。另外，你可以使用 <code>-ucp-ca</code> 选项来直接指定 UCP 的 CA 证书。</p><p>然后 DTR bootstrap 镜像会让你确定几项设置，比如 UCP 安装的 URL 地址以及管理员的用户名和密码。从拉取所有的 DTR 镜像到设置全部完成，只需要一到两分钟的时间。</p><h3 id="保证一切安全" tabindex="-1">保证一切安全 <a class="header-anchor" href="#保证一切安全" aria-label="Permalink to “保证一切安全”">​</a></h3><p>一切都准备好后，就可以向注册服务器推送或者从中拉取镜像了。在做这一步之前，让我们设置 TLS 证书，以便与 DTR 安全地通信。</p><p>在 Linux 上，我们可以使用以下命令（只需确保更改了 <code>DTR_HOSTNAME</code> 变量，来正确映射我们刚刚设置的 DTR）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 从 DTR 拉取 CA 证书（如果 curl 不可用，你可以使用 wget）</span></span>
<span class="line"><span>DTR_HOSTNAME=&lt; DTR 主机名&gt;</span></span>
<span class="line"><span>curl -k https://$(DTR_HOSTNAME)/ca &gt; $(DTR_HOSTNAME).crt</span></span>
<span class="line"><span>sudo mkdir /etc/docker/certs.d/$(DTR_HOSTNAME)</span></span>
<span class="line"><span>sudo cp $(DTR_HOSTNAME) /etc/docker/certs.d/$(DTR_HOSTNAME)</span></span>
<span class="line"><span># 重启 docker 守护进程（在 Ubuntu 14.04 上，使用 \`sudo service docker restart\` 命令）</span></span>
<span class="line"><span>sudo systemctl restart docker</span></span></code></pre></div><p>对于 Mac 和 Windows 版的 Docker，我们会以不同的方式安装客户端。转入“设置 -&gt; 守护进程”，在“不安全的注册服务器”部分，输入你的 DTR 主机名。点击“应用”，docker 守护进程应在重启后可以良好使用。</p><h3 id="推送和拉取镜像" tabindex="-1">推送和拉取镜像 <a class="header-anchor" href="#推送和拉取镜像" aria-label="Permalink to “推送和拉取镜像”">​</a></h3><p>现在我们需要设置一个仓库来存放镜像。这和 Docker Hub 有一点不同，如果你做的 docker 推送仓库中不存在，它会自动创建一个。要创建一个仓库，在浏览器中打开 <code>https://&lt;Your DTR hostname&gt;</code> 并在出现登录提示时使用你的管理员凭据登录。如果你向 UCP 添加了许可证，则 DTR 会自动获取该许可证。如果没有，请现在确认上传你的许可证。</p><p>进入刚才的网页之后，点击“新建仓库”按钮来创建新的仓库。</p><p>我们会创建一个用于存储 Alpine linux 的仓库，所以在名字输入处键入 “alpine”，点击“保存”（在 DTR 2.5 及更高版本中叫“创建”）。</p><p>现在我们回到 shell 界面输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 拉取 Alpine Linux 的最新版</span></span>
<span class="line"><span>docker pull alpine:latest</span></span>
<span class="line"><span># 登入新的 DTR 实例</span></span>
<span class="line"><span>docker login &lt;Your DTR hostname&gt;</span></span>
<span class="line"><span># 标记上 Alpine 使能推送其至你的 DTR</span></span>
<span class="line"><span>docker tag alpine:latest &lt;Your DTR hostname&gt;/admin/alpine:latest</span></span>
<span class="line"><span># 向 DTR 推送镜像</span></span>
<span class="line"><span>docker push &lt;Your DTR hostname&gt;/admin/alpine:latest</span></span></code></pre></div><p>就是这样！我们刚刚推送了最新的 Alpine Linux 的一份拷贝，重新打了标签以便将其存储到 DTR 中，并将其推送到我们的私有注册服务器。如果你想将镜像拉取至不同的 Docker 引擎中，按如上所示设置你的 DTR 证书，然后执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 从 DTR 中拉取镜像</span></span>
<span class="line"><span>docker pull &lt;Your DTR hostname&gt;/admin/alpine:latest</span></span></code></pre></div><p>DTR 具有许多优秀的镜像管理功能，例如镜像的缓存、映像、扫描、签名甚至自动化供应链策略。这些功能我们在后期的博客文章中更详细的探讨。</p><hr>`,23)),t("p",null,[s[14]||(s[14]=e("via: ",-1)),a(n,{href:"https://blog.docker.com/2018/01/dtr/"},{default:i(()=>[...s[13]||(s[13]=[e("https://blog.docker.com/2018/01/dtr/",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=e("作者：",-1)),a(n,{href:"https://blog.docker.com/author/pdevine/"},{default:i(()=>[...s[15]||(s[15]=[e("Patrick Devine",-1)])]),_:1}),s[19]||(s[19]=e(" 译者：",-1)),a(n,{href:"https://github.com/fuowang"},{default:i(()=>[...s[16]||(s[16]=[e("fuowang",-1)])]),_:1}),s[20]||(s[20]=e(" 校对：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[23]||(s[23]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原创编译，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[e("Linux中国",-1)])]),_:1}),s[25]||(s[25]=e(" 荣誉推出",-1))])])}const R=p(k,[["render",u]]);export{m as __pageData,R as default};
